];

$db=db();
$lesson=query_one("SELECT l.id,l.grade_id,l.subject_id,l.unit_id FROM lessons l JOIN grades g ON g.id=l.grade_id JOIN subjects s ON s.id=l.subject_id WHERE g.grade_number=10 AND s.name_en='Buddhism' AND l.medium='Sinhala' AND l.display_order=1 AND l.title_si='අභියෝග ජය ගත් සිදුහත් බෝසතාණෝ' AND l.status='active' LIMIT 1");
if(!$lesson)throw new RuntimeException('Grade 10 Sinhala Buddhism lesson 1 was not found.');
$quiz=query_one("SELECT id FROM quizzes WHERE lesson_id=? AND status='active' ORDER BY id LIMIT 1",'i',[(int)$lesson['id']]);
if(!$quiz){$add=$db->prepare("INSERT INTO quizzes(grade_id,subject_id,unit_id,lesson_id,title_si,timer_minutes,pass_mark,status) VALUES(?,?,?,?,?,30,50,'active')");$title='1 වන පාඩම — MCQ ප්‍රශ්න 30';$add->bind_param('iiiis',$lesson['grade_id'],$lesson['subject_id'],$lesson['unit_id'],$lesson['id'],$title);$add->execute();$quizId=(int)$db->insert_id;}else{$quizId=(int)$quiz['id'];$db->query("UPDATE quizzes SET title_si='1 වන පාඩම — MCQ ප්‍රශ්න 30',timer_minutes=30,pass_mark=50,status='active' WHERE id=$quizId");}
$db->begin_transaction();
try{
 $deleteAnswers=$db->prepare("DELETE qa FROM quiz_answers qa JOIN quiz_questions qq ON qq.id=qa.question_id WHERE qq.quiz_id=? AND qq.activity_type='challenge'");$deleteAnswers->bind_param('i',$quizId);$deleteAnswers->execute();
 $delete=$db->prepare("DELETE FROM quiz_questions WHERE quiz_id=? AND activity_type='challenge'");$delete->bind_param('i',$quizId);$delete->execute();
 $insert=$db->prepare("INSERT INTO quiz_questions(quiz_id,activity_type,question_si,option_a_si,option_b_si,option_c_si,option_d_si,correct_option,explanation_si,display_order,status) VALUES(?,'challenge',?,?,?,?,?,?,?,?,'active')");
 foreach($questions as $i=>$question){[$text,$options,$correct,$explanation]=$question;$order=$i+1;$insert->bind_param('isssssssi',$quizId,$text,$options[0],$options[1],$options[2],$options[3],$correct,$explanation,$order);if(!$insert->execute())throw new RuntimeException($insert->error);}
 $count=(int)(query_one("SELECT COUNT(*) total FROM quiz_questions WHERE quiz_id=? AND activity_type='challenge' AND status='active'",'i',[$quizId])['total']??0);if($count!==30)throw new RuntimeException("Expected 30 MCQs, found $count.");
 $db->commit();echo "Grade 10 Buddhism lesson 1 replaced with 30 MCQs.\n";
}catch(Throwable $error){$db->rollback();throw $error;}
